// ===== STORE CONFIG — alleen dit blok aanpassen per store =====
const STORE = {
  name: 'Store Name',                    // bv. 'Lady Glam Boutique'
  domain: 'store.com',                   // publiek domein
  shop: 'xxxxx.myshopify.com',           // myshopify-domein
  client_id: 'SHOPIFY_CLIENT_ID',        // Dev Dashboard app
  client_secret: 'SHOPIFY_CLIENT_SECRET',
  market: 'customers in the USA',        // bv. 'customers in Australia and New Zealand'
  currency: 'USD',
  exchange_fee: '10',                    // vaste verzendkosten bij maatruil
  partial_refund_pct: '20',              // % partial refund bij 'houden'
  signoff: 'The Store Name Team',
  slack_channel: '#cs-alerts'
};
// ==============================================================

const SKIP_SENDERS = /(no-?reply|mailer-daemon|postmaster|notifications?@|@shopify\.com|@google\.com|@facebookmail|@klaviyo|@paypal|@stripe|@tiktok|@trackbee)/i;

const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const fromObj = (m.from && m.from.value && m.from.value[0]) || {};
  const from = (fromObj.address || '').toLowerCase();
  if (!from || SKIP_SENDERS.test(from)) continue;

  let body = m.text || (m.html || '').replace(/<[^>]+>/g, ' ');
  body = body.replace(/\s+\n/g, '\n').slice(0, 6000);
  const subject = m.subject || '';
  const numMatch = (subject + ' ' + body).match(/#?\b(\d{4,6})\b/);

  out.push({ json: {
    store: STORE,
    email: {
      id: m.id,
      threadId: m.threadId,
      from,
      from_name: fromObj.name || '',
      subject,
      reply_subject: /^re:/i.test(subject) ? subject : 'Re: ' + subject,
      body,
      order_number_guess: numMatch ? numMatch[1] : ''
    }
  }});
}
return out;

const base = $('Store Config + filter').item.json;
const orders = ($json.data && $json.data.orders && $json.data.orders.nodes) || [];
const slim = orders.map(o => ({
  order: o.name,
  shopify_id: o.id,
  date: o.createdAt.slice(0,10),
  paid: o.displayFinancialStatus,
  fulfillment: o.displayFulfillmentStatus,
  cancelled: !!o.cancelledAt,
  total: o.totalPriceSet.shopMoney.amount + ' ' + o.totalPriceSet.shopMoney.currencyCode,
  customer: [o.customer?.firstName, o.customer?.lastName].filter(Boolean).join(' '),
  ship_to: o.shippingAddress ? o.shippingAddress.city + ', ' + o.shippingAddress.countryCodeV2 : '',
  items: o.lineItems.nodes.map(li => `${li.quantity}x ${li.title}${li.variantTitle ? ' (' + li.variantTitle + ')' : ''}`),
  tracking: o.fulfillments.flatMap(f => f.trackingInfo.map(t => ({ company: t.company, number: t.number, url: t.url, shipped: f.createdAt.slice(0,10) })))
}));
return [{ json: { store: base.store, email: base.email, orders: slim } }];
